// Generated by scripts/sync-website-demos.mjs from the website tool pages. Edit the website copy and re-run.
import { Btn, DemoStage, Field, PanelChrome, Toggle, type Build } from '@/app/demos/stage'

import { CAPTIONS, CASE_MATCHES, FIND, MATCHES_LOOSE, REPLACE, ROWS } from './script'

const build: Build = ({ tl, q, qa, step, final, move, click, type, count, wait, cursorOut }) => {
  const matches = qa('m')
  const lower = qa('m-lower')

  step(0)
  move('find-text', { at: 0.3, ax: 0.2 })
  click('find-text')
  type('find-text', FIND, { speed: 0.07 })
  tl.to(q('spot'), {
    keyframes: { x: [-60, 330], opacity: [0, 1, 1, 0] },
    duration: 1.1,
    ease: 'power1.inOut',
  })
  tl.to(
    matches,
    { backgroundColor: 'rgba(251,191,36,0.35)', color: '#fde68a', duration: 0.2, stagger: 0.12 },
    '<0.2',
  )
  count('count', MATCHES_LOOSE, { at: '<', duration: 0.4 })

  step(1, '+=0.4')
  move('case')
  click('case')
  tl.to(q('case-fill'), { opacity: 1, duration: 0.2 }, '<')
  tl.to(q('case-knob'), { x: 12, duration: 0.25 }, '<')
  tl.to(
    q('m-upper'),
    { backgroundColor: 'rgba(251,191,36,0)', color: '#8b8b9a', duration: 0.3 },
    '<0.1',
  )
  count('count', CASE_MATCHES, { at: '<', from: MATCHES_LOOSE, duration: 0.3 })

  step(2, '+=0.4')
  move('replace-text', { ax: 0.2 })
  click('replace-text')
  type('replace-text', REPLACE, { speed: 0.07 })
  tl.to(
    qa('old'),
    { rotateX: 90, opacity: 0, duration: 0.25, stagger: 0.08, ease: 'power2.in' },
    '+=0.1',
  )
  tl.fromTo(
    qa('new'),
    { rotateX: -90, opacity: 0 },
    { rotateX: 0, opacity: 1, duration: 0.4, stagger: 0.08, ease: 'back.out(2)' },
    '<0.15',
  )

  step(3, '+=0.5')
  move('all')
  click('all')
  tl.to(
    lower,
    { backgroundColor: 'rgba(52,211,153,0.3)', color: '#a7f3d0', duration: 0.25, stagger: 0.05 },
    '<',
  )
  tl.to(
    lower,
    { backgroundColor: 'rgba(52,211,153,0)', color: '#d4d4de', duration: 0.5, stagger: 0.05 },
    '+=0.5',
  )
  tl.fromTo(q('done'), { opacity: 0, y: 6 }, { opacity: 1, y: 0, duration: 0.3 }, '<')
  cursorOut('+=0.2')
  final()
  wait(1.4)
}

export default function Demo() {
  return (
    <DemoStage
      label="Find and Replace highlighting matches, turning on match case and replacing every match"
      steps={CAPTIONS}
      build={build}
    >
      <PanelChrome
        aside={
          <span className="rounded-full border border-line-strong px-2.5 py-1 font-mono text-[10px]">
            <span data-d="count" className="text-amber">
              0
            </span>{' '}
            matches
          </span>
        }
      >
        <div className="flex h-full flex-col gap-2.5">
          <div className="grid grid-cols-2 gap-2">
            <Field label="Find" d="find-text" mono />
            <Field label="Replace with" d="replace-text" mono />
          </div>
          <div className="flex items-center gap-4 text-[10px] text-muted">
            <span className="flex items-center gap-1.5">
              <Toggle d="case" /> Case-sensitive
            </span>
            <span className="flex items-center gap-1.5">
              <Toggle /> Whole word
            </span>
            <span className="flex items-center gap-1.5">
              <Toggle /> Regex
            </span>
          </div>
          <div className="relative min-h-0 flex-1 overflow-hidden rounded-xl border border-line bg-canvas/80 p-3 font-mono text-[11.5px] leading-[24px] text-ink-soft [perspective:500px]">
            {ROWS.map((row) => (
              <p key={row.label}>
                <span className="text-muted">{row.label}: </span>
                <span
                  data-d={`m ${row.upper ? 'm-upper' : 'm-lower'}`}
                  className="inline-grid rounded px-0.5"
                >
                  <span data-d={row.upper ? undefined : 'old'} className="[grid-area:1/1]">
                    {row.upper ? FIND.toUpperCase() : FIND}
                  </span>
                  {row.upper ? null : (
                    <span data-d="new" className="opacity-0 [grid-area:1/1]">
                      {REPLACE}
                    </span>
                  )}
                </span>
                {row.rest}
              </p>
            ))}
            <span
              data-d="spot"
              className="pointer-events-none absolute top-0 h-full w-24 opacity-0"
              style={{
                background:
                  'radial-gradient(50% 60% at 50% 50%, rgba(251,191,36,0.22), transparent 70%)',
              }}
            />
          </div>
          <div className="flex items-center gap-2">
            <Btn d="all" primary>
              Replace all
            </Btn>
            <span data-d="done" className="text-[10.5px] text-emerald opacity-0">
              {CASE_MATCHES} replaced
            </span>
          </div>
        </div>
      </PanelChrome>
    </DemoStage>
  )
}
